        int a_col = t * TILE_SIZE + tx * 2;
        if (row0 < N && a_col < N) {
            As[ty*2][tx*2] = A[row0 * N + a_col];
            As[ty*2][tx*2+1] = A[row0 * N + a_col + 1];
